<?php
namespace App\Http\Controllers;
use App\Repositories\{LojaRepository,ClienteRepository,LancamentoRepository,PagamentoRepository,UsuarioRepository,AuditoriaRepository}; use App\Services\{ClienteService,WhatsappService}; use Illuminate\Http\Request;
class AppController extends Controller {
 public function __construct(private ClienteRepository $clientes,private LancamentoRepository $lancamentos,private PagamentoRepository $pagamentos,private LojaRepository $lojas,private ClienteService $clientService,private WhatsappService $whatsapp){}
 private function clients():array{return $this->clientes->where('loja_id',session('loja_id'));} private function launches():array{return $this->lancamentos->where('loja_id',session('loja_id'));} private function pays():array{return $this->pagamentos->where('loja_id',session('loja_id'));}
 public function dashboard(){ $cs=collect($this->clients());$ls=collect($this->launches());$ps=collect($this->pays());$open=$ls->where('status','!=','cancelado');$balances=$cs->map(fn($c)=>$this->clientService->balance($c['id']));$overdue=$open->filter(fn($l)=>($l['data_vencimento']??'')<today()->toDateString());$today=$ps->filter(fn($p)=>str_starts_with($p['data_pagamento']??'',today()->toDateString()))->sum('valor');$rank=$cs->map(fn($c)=>['cliente'=>$c,'saldo'=>$this->clientService->balance($c['id'])])->sortByDesc('saldo')->values();return view('app.dashboard',compact('cs','ls','ps','open','overdue','today','rank','balances'));}
 public function balcao(Request $r){$q=$r->get('q','');$clients=collect($this->clients())->filter(fn($c)=>!$q||str_contains(strtolower(($c['nome']??'').' '.($c['apelido']??'').' '.($c['telefone']??'')),strtolower($q)));return view('app.balcao',compact('clients','q'));}
 public function inadimplentes(Request $r){$kind=$r->get('filtro','todos');$items=collect($this->launches())->filter(fn($l)=>($l['data_vencimento']??'')<today()->toDateString() && $l['status']!=='cancelado')->groupBy('cliente_id')->map(function($ls,$id){$c=$this->clientService->owned($id);$days=today()->diffInDays(collect($ls)->min('data_vencimento'));return ['cliente'=>$c,'saldo'=>$this->clientService->balance($id),'dias'=>$days];})->filter(fn($i)=>$i['cliente']);if($kind==='1-7')$items=$items->filter(fn($i)=>$i['dias']<=7);if($kind==='8-15')$items=$items->filter(fn($i)=>$i['dias']>=8&&$i['dias']<=15);if($kind==='16-30')$items=$items->filter(fn($i)=>$i['dias']>=16&&$i['dias']<=30);if($kind==='30+')$items=$items->filter(fn($i)=>$i['dias']>30);return view('app.inadimplentes',['items'=>$items->sortByDesc('saldo'),'filtro'=>$kind]);}
 public function reports(){return view('app.reports',['clients'=>$this->clients(),'lancamentos'=>$this->launches(),'pagamentos'=>$this->pays()]);}
 public function assistant(){return view('app.assistant',['items'=>collect($this->clients())->map(fn($c)=>['cliente'=>$c,'saldo'=>$this->clientService->balance($c['id'])])->filter(fn($i)=>$i['saldo']>0)->sortByDesc('saldo')]);}
 public function config(){return view('app.config',['loja'=>$this->lojas->find(session('loja_id'))]);}
 public function updateConfig(Request $r){$d=$r->validate(['chave_pix'=>'nullable|max:120','telefone'=>'required','cidade'=>'required','estado'=>'required|max:2']);$this->lojas->update(session('loja_id'),$d);return back()->with('success','Configurações atualizadas.');}
 public function users(UsuarioRepository $users){return view('app.users',['users'=>$users->where('loja_id',session('loja_id'))]);}
 public function publicClient(string $token){$c=collect($this->clientes->all())->firstWhere('token_consulta',$token);abort_unless($c,404);$loja=$this->lojas->find($c['loja_id']);return view('public.client',array_merge($this->clientService->detail($c),compact('loja')));}
 public function whatsapp(string $id){$c=$this->clientService->owned($id);abort_unless($c,404);return redirect()->away($this->whatsapp->link($this->lojas->find(session('loja_id')),$c,$this->clientService->balance($id)));}
}
